import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum UserRole {
  FARMER = 'FARMER',
  BUYER = 'BUYER',
  ADMIN = 'ADMIN'
}

export enum CertType {
  VIETGAP = 'VietGAP',
  GLOBALGAP = 'GlobalGAP',
  OCOP = 'OCOP',
  ORGANIC = 'Hữu cơ'
}

export enum ProductStatus {
  PENDING = 'Chờ duyệt',
  APPROVED = 'Đã duyệt',
  REJECTED = 'Từ chối'
}

export interface FarmLocation {
  lat: number;
  lng: number;
  address: string;
}

export interface FarmProduct {
  id: string;
  farmerId: string;
  farmerName: string;
  name: string;
  category: string;
  description: string;
  images: string[];
  certificates: CertType[];
  regionCode: string;
  location: FarmLocation;
  status: ProductStatus;
  contact: string;
  rating: number;
  updatedAt: string;
}

export interface Statistics {
  totalFarms: number;
  totalProducts: number;
  certifiedFarms: number;
  pendingApprovals: number;
}

import React, { useState, useMemo } from 'react';
import { UserRole, FarmProduct } from './types';
import { MOCK_PRODUCTS } from './constants';
import Navbar from './components/Navbar';
import MapInterface from './components/MapInterface';
import FarmerPortal from './components/FarmerPortal';
import AdminDashboard from './components/AdminDashboard';

const App: React.FC = () => {
  const [currentRole, setCurrentRole] = useState<UserRole>(UserRole.BUYER);
  const [products, setProducts] = useState<FarmProduct[]>(MOCK_PRODUCTS);
  const [searchQuery, setSearchQuery] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('All');

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const matchesSearch = p.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                          p.farmerName.toLowerCase().includes(searchQuery.toLowerCase());
      const matchesCategory = categoryFilter === 'All' || p.category === categoryFilter;
      const isAdminView = currentRole === UserRole.ADMIN;
      const isApproved = p.status === 'Đã duyệt';

      // Admin sees everything, others see only approved
      return matchesSearch && matchesCategory && (isAdminView || isApproved);
    });
  }, [products, searchQuery, categoryFilter, currentRole]);

  const handleAddProduct = (newProduct: FarmProduct) => {
    setProducts(prev => [newProduct, ...prev]);
    setCurrentRole(UserRole.BUYER); // Switch back to see result
  };

  const handleUpdateStatus = (id: string, status: any) => {
    setProducts(prev => prev.map(p => p.id === id ? { ...p, status } : p));
  };

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-slate-50">
      <Navbar 
        currentRole={currentRole} 
        onRoleChange={setCurrentRole}
        onSearch={setSearchQuery}
      />

      <main className="flex-1 relative overflow-hidden">
        {currentRole === UserRole.BUYER && (
          <div className="h-full flex flex-col md:flex-row">
            <div className="w-full md:w-1/3 lg:w-1/4 h-1/3 md:h-full border-r bg-white overflow-y-auto p-4 z-10 shadow-lg">
              <h2 className="text-xl font-bold text-green-800 mb-4">Khám phá Nông sản</h2>
              <div className="space-y-4">
                <select 
                  className="w-full p-2 border rounded-lg outline-none focus:ring-2 focus:ring-green-500"
                  onChange={(e) => setCategoryFilter(e.target.value)}
                  value={categoryFilter}
                >
                  <option value="All">Tất cả danh mục</option>
                  <option value="Trái cây">Trái cây</option>
                  <option value="Lúa gạo">Lúa gạo</option>
                  <option value="Rau củ">Rau củ</option>
                </select>

                <div className="space-y-3">
                  {filteredProducts.map(product => (
                    <div key={product.id} className="p-3 border rounded-xl hover:border-green-500 cursor-pointer transition-all bg-white shadow-sm group">
                      <img src={product.images[0]} alt={product.name} className="w-full h-32 object-cover rounded-lg mb-2" />
                      <h3 className="font-bold text-slate-800 group-hover:text-green-700">{product.name}</h3>
                      <p className="text-xs text-slate-500">{product.farmerName}</p>
                      <div className="flex flex-wrap gap-1 mt-2">
                        {product.certificates.map(c => (
                          <span key={c} className="px-2 py-0.5 bg-green-100 text-green-700 text-[10px] rounded-full font-semibold">{c}</span>
                        ))}
                      </div>
                    </div>
                  ))}
                  {filteredProducts.length === 0 && (
                    <p className="text-center text-slate-400 py-10 italic">Không tìm thấy sản phẩm phù hợp.</p>
                  )}
                </div>
              </div>
            </div>
            <div className="flex-1 h-full">
              <MapInterface products={filteredProducts} />
            </div>
          </div>
        )}

        {currentRole === UserRole.FARMER && (
          <div className="h-full overflow-y-auto bg-green-50/30">
             <FarmerPortal onAdd={handleAddProduct} />
          </div>
        )}

        {currentRole === UserRole.ADMIN && (
          <div className="h-full overflow-y-auto p-6">
            <AdminDashboard 
              products={products} 
              onUpdateStatus={handleUpdateStatus} 
            />
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React from 'react';
import { UserRole } from '../types';
import { Map, LayoutDashboard, User, Search, Sprout } from 'lucide-react';

