        >
          <User size={16} />
          <span>Nông hộ</span>
        </button>
        <button 
          onClick={() => onRoleChange(UserRole.ADMIN)}
          className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-sm font-medium transition-all ${currentRole === UserRole.ADMIN ? 'bg-white text-green-700 shadow-sm' : 'text-slate-500 hover:text-green-600'}`}
        >
          <LayoutDashboard size={16} />
          <span>Quản trị</span>
        </button>
      </div>
    </nav>
  );
};

export default Navbar;

import React, { useEffect, useRef, useState } from 'react';
import L from 'leaflet';
import { FarmProduct } from '../types';
import { MapPin, Phone, Star, Award, ExternalLink } from 'lucide-react';

interface MapInterfaceProps {
  products: FarmProduct[];
}

const MapInterface: React.FC<MapInterfaceProps> = ({ products }) => {
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<L.Map | null>(null);
  const markersRef = useRef<L.Marker[]>([]);
  const [selectedProduct, setSelectedProduct] = useState<FarmProduct | null>(null);

  useEffect(() => {
    if (!mapContainerRef.current) return;

    if (!mapRef.current) {
      mapRef.current = L.map(mapContainerRef.current, {
        center: [15.8, 108.2], // Center of Vietnam
        zoom: 6,
        zoomControl: false
      });

      L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        attribution: '© OpenStreetMap contributors'
      }).addTo(mapRef.current);

      L.control.zoom({ position: 'bottomright' }).addTo(mapRef.current);
    }

    // Clear existing markers
    markersRef.current.forEach(m => m.remove());
    markersRef.current = [];

    // Custom Icon Factory
    const createIcon = (category: string) => L.divIcon({
      className: 'custom-div-icon',
      html: `<div class="bg-green-600 p-2 rounded-full border-2 border-white shadow-xl transform transition hover:scale-110">
              <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-leaf"><path d="M11 20A7 7 0 0 1 9.8 6.1C15.5 5 17 4.48 19 2c1 2 2 3.5 2 9.5a7 7 0 0 1-7 7c-2 0-3-1-3-1"/><path d="M11 20s-1 1.5-3.5 1.5-4.5-1.5-4.5-5 4-5 4-5"/></svg>
            </div>`,
      iconSize: [32, 32],
      iconAnchor: [16, 32],
    });

    // Add markers
    products.forEach(p => {
      const marker = L.marker([p.location.lat, p.location.lng], {
        icon: createIcon(p.category)
      })
      .addTo(mapRef.current!)
      .on('click', () => setSelectedProduct(p));

      markersRef.current.push(marker);
    });

    return () => {
      // Clean up if needed, though with mapRef persist we mostly just manage markers
    };
  }, [products]);

  return (
    <div className="relative w-full h-full">
      <div ref={mapContainerRef} className="w-full h-full z-0" />

      {selectedProduct && (
        <div className="absolute bottom-6 left-1/2 transform -translate-x-1/2 w-full max-w-sm px-4 z-[1000] animate-in slide-in-from-bottom-10 duration-300">
          <div className="bg-white rounded-3xl shadow-2xl border border-green-100 overflow-hidden">
            <div className="relative h-48">
              <img src={selectedProduct.images[0]} alt={selectedProduct.name} className="w-full h-full object-cover" />
              <button 
                onClick={() => setSelectedProduct(null)}
                className="absolute top-3 right-3 bg-black/30 hover:bg-black/50 text-white p-1.5 rounded-full backdrop-blur-sm transition-all"
              >
                <svg width="20" height="20" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
              </button>
              <div className="absolute bottom-3 left-3 bg-white/90 backdrop-blur px-3 py-1 rounded-full flex items-center gap-1">
                <Star className="text-yellow-500 fill-yellow-500" size={14} />
                <span className="text-sm font-bold text-slate-800">{selectedProduct.rating}</span>
              </div>
            </div>

            <div className="p-5">
              <div className="flex justify-between items-start mb-2">
                <div>
                  <h3 className="text-xl font-bold text-slate-800 leading-tight">{selectedProduct.name}</h3>
                  <p className="text-sm text-green-600 font-medium">{selectedProduct.farmerName}</p>
                </div>
                <div className="bg-green-50 px-2 py-1 rounded-lg">
                  <span className="text-[10px] font-bold text-green-700 uppercase">{selectedProduct.category}</span>
                </div>
              </div>

              <div className="flex items-center gap-2 text-slate-500 text-sm mb-4">
                <MapPin size={14} />
                <span>{selectedProduct.location.address}</span>
              </div>

              <div className="flex flex-wrap gap-2 mb-6">
                {selectedProduct.certificates.map(c => (
                  <div key={c} className="flex items-center gap-1 bg-green-50 border border-green-100 px-2 py-1 rounded-md">
                    <Award size={12} className="text-green-600" />
                    <span className="text-xs font-semibold text-green-700">{c}</span>
                  </div>
                ))}
              </div>

              <div className="flex gap-2">
                <a 
                  href={`tel:${selectedProduct.contact}`}
                  className="flex-1 bg-green-600 hover:bg-green-700 text-white py-2.5 rounded-xl font-bold text-center flex items-center justify-center gap-2 transition-all shadow-lg shadow-green-200"
                >
                  <Phone size={18} />
                  Gọi Liên Hệ
                </a>
                <button className="p-2.5 border-2 border-slate-100 rounded-xl hover:border-green-200 transition-all text-slate-400 hover:text-green-600">
                  <ExternalLink size={20} />
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default MapInterface;

import React, { useState } from 'react';
import { FarmProduct, ProductStatus, CertType } from '../types';
import { CATEGORIES } from '../constants';
import { PackagePlus, Upload, ShieldCheck, MapPinned } from 'lucide-react';

interface FarmerPortalProps {
  onAdd: (product: FarmProduct) => void;
}

const FarmerPortal: React.FC<FarmerPortalProps> = ({ onAdd }) => {
  const [formData, setFormData] = useState({
    name: '',
    category: CATEGORIES[0],
    description: '',
    contact: '',
    regionCode: '',
    address: 'Vĩnh Long, Việt Nam',
    certs: [] as CertType[]
  });

  const handleToggleCert = (cert: CertType) => {
    setFormData(prev => ({
      ...prev,
      certs: prev.certs.includes(cert) 
        ? prev.certs.filter(c => c !== cert) 
        : [...prev.certs, cert]
    }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newProduct: FarmProduct = {
      id: Math.random().toString(36).substr(2, 9),
      farmerId: 'f_current',
      farmerName: 'Vườn Nhà Tôi',
      name: formData.name,
      category: formData.category,
      description: formData.description,
      images: [`https://picsum.photos/seed/${formData.name}/600/400`],
      certificates: formData.certs,
      regionCode: formData.regionCode,
      location: { 
        lat: 10.2 + Math.random() * 2, 
        lng: 105.8 + Math.random() * 2, 
        address: formData.address 
      },
      status: ProductStatus.PENDING,
      contact: formData.contact,
      rating: 0,
      updatedAt: new Date().toISOString().split('T')[0]
    };
    onAdd(newProduct);
  };

  return (
    <div className="max-w-4xl mx-auto py-10 px-6">
      <div className="bg-white rounded-3xl shadow-sm border p-8">
        <div className="flex items-center gap-3 mb-8">
          <div className="bg-green-100 p-3 rounded-2xl text-green-700">
            <PackagePlus size={32} />
          </div>
          <div>
            <h2 className="text-2xl font-bold text-slate-800">Đăng ký Nông sản mới</h2>
            <p className="text-slate-500">Thông tin của bạn sẽ được Bộ Nông nghiệp kiểm duyệt trước khi hiển thị trên bản đồ.</p>
          </div>
        </div>

        <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-2 gap-8">
          <div className="space-y-6">
            <div>
              <label className="block text-sm font-bold text-slate-700 mb-2">Tên nông sản *</label>
              <input 
                required
                type="text" 
                placeholder="Ví dụ: Dưa lưới Huỳnh Long"
                className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-green-500 transition-all"
                value={formData.name}
                onChange={e => setFormData({...formData, name: e.target.value})}
              />
            </div>

            <div>
              <label className="block text-sm font-bold text-slate-700 mb-2">Loại nông sản</label>
              <select 
                className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-green-500 transition-all"
                value={formData.category}
                onChange={e => setFormData({...formData, category: e.target.value})}
              >
                {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
              </select>
            </div>

            <div>
              <label className="block text-sm font-bold text-slate-700 mb-2">Mô tả sản phẩm</label>
              <textarea 
                rows={4}
                placeholder="Chia sẻ về quy trình canh tác, đặc điểm sản phẩm..."
                className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-green-500 transition-all resize-none"
                value={formData.description}
                onChange={e => setFormData({...formData, description: e.target.value})}
              ></textarea>
            </div>

            <div>
              <label className="block text-sm font-bold text-slate-700 mb-2">Mã số vùng trồng</label>
              <input 
                type="text" 
                placeholder="Ví dụ: VL-12345"
                className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-green-500 transition-all"
                value={formData.regionCode}
                onChange={e => setFormData({...formData, regionCode: e.target.value})}
              />
            </div>
          </div>

          <div className="space-y-6">
            <div className="p-6 bg-green-50 rounded-2xl border border-green-100">
              <div className="flex items-center gap-2 mb-4 text-green-800 font-bold">
                <ShieldCheck size={20} />
                <span>Chứng chỉ & Tín chỉ</span>
              </div>
              <div className="grid grid-cols-2 gap-3">
                {Object.values(CertType).map(cert => (
                  <button
                    key={cert}
                    type="button"
                    onClick={() => handleToggleCert(cert)}
                    className={`px-4 py-2 rounded-lg text-xs font-bold transition-all border ${formData.certs.includes(cert) ? 'bg-green-600 text-white border-green-600' : 'bg-white text-slate-500 border-slate-200 hover:border-green-300'}`}
                  >
                    {cert}
                  </button>
                ))}
              </div>
            </div>

            <div>
              <label className="block text-sm font-bold text-slate-700 mb-2">Vị trí Nông trại (GPS)</label>
              <div className="relative group">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <MapPinned className="text-slate-400" size={18} />
                </div>
                <input 
                  type="text" 
                  readOnly
                  className="w-full p-3 pl-10 bg-slate-50 border border-slate-200 rounded-xl outline-none cursor-default"
                  value={formData.address}
                />
                <button type="button" className="mt-2 text-green-600 text-sm font-semibold hover:underline">Chọn lại trên bản đồ</button>
              </div>
            </div>

            <div>
              <label className="block text-sm font-bold text-slate-700 mb-2">Hình ảnh sản phẩm</label>
              <div className="border-2 border-dashed border-slate-200 rounded-2xl p-6 flex flex-col items-center justify-center hover:bg-slate-50 transition-all cursor-pointer">
                <Upload className="text-slate-300 mb-2" size={32} />
                <p className="text-xs text-slate-400">Tải lên ít nhất 1 ảnh (PNG, JPG)</p>
              </div>
            </div>

            <button 
              type="submit"
              className="w-full bg-green-700 hover:bg-green-800 text-white py-4 rounded-2xl font-bold text-lg shadow-xl shadow-green-200 transition-all transform hover:-translate-y-1"
            >
              Gửi yêu cầu xét duyệt
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default FarmerPortal;

export enum UserRole {
  FARMER = 'FARMER',
  BUYER = 'BUYER',
  ADMIN = 'ADMIN'
}

export enum CertType {
  VIETGAP = 'VietGAP',
  GLOBALGAP = 'GlobalGAP',
  OCOP = 'OCOP',
  ORGANIC = 'Hữu cơ'
}

export enum ProductStatus {
  PENDING = 'Chờ duyệt',
