import React, { useState, useEffect } from 'react';
import { FarmProduct, ProductStatus, CertType, FarmingTimelineUpdate } from '../types';
import { CATEGORIES } from '../constants';
import { 
  PackagePlus, Upload, ShieldCheck, MapPinned, 
  Calendar, Info, AlertTriangle, CheckCircle2, 
  PlusCircle, Camera, QrCode, History 
} from 'lucide-react';

interface FarmerPortalProps {
  onAdd: (product: FarmProduct) => void;
}

const FarmerPortal: React.FC<FarmerPortalProps> = ({ onAdd }) => {
  const [activeTab, setActiveTab] = useState<'register' | 'my-farms'>('register');

  // State cho Form
  const [formData, setFormData] = useState({
    name: '',
    variety: '',
    category: CATEGORIES[0],
    area: 0,
    yield: 0,
    description: '',
    contact: '',
    regionCode: '',
    address: 'Vĩnh Long, Việt Nam',
    harvestMonths: [] as number[],
    certs: [] as { type: CertType, proofUrl: string }[],
  });

  const [images, setImages] = useState({
