import React, { useState, useMemo } from 'react';
import { UserRole, FarmProduct, ProductStatus } from './types';
import { MOCK_PRODUCTS } from './constants';
import Navbar from './components/Navbar';
import MapInterface from './components/MapInterface';
import FarmerPortal from './components/FarmerPortal';
import AdminDashboard from './components/AdminDashboard';

const App: React.FC = () => {
  const [currentRole, setCurrentRole] = useState<UserRole>(UserRole.BUYER);
  const [products, setProducts] = useState<FarmProduct[]>(MOCK_PRODUCTS);
  const [searchQuery, setSearchQuery] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('All');

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const matchesSearch = p.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                          p.farmerName.toLowerCase().includes(searchQuery.toLowerCase());
      const matchesCategory = categoryFilter === 'All' || p.category === categoryFilter;
      const isAdminView = currentRole === UserRole.ADMIN;
      const isApproved = p.status === ProductStatus.APPROVED;

      // Admin sees everything, others see only approved
      return matchesSearch && matchesCategory && (isAdminView || isApproved);
    });
  }, [products, searchQuery, categoryFilter, currentRole]);

  const handleAddProduct = (newProduct: FarmProduct) => {
    setProducts(prev => [newProduct, ...prev]);
    setCurrentRole(UserRole.BUYER); // Switch back to see result
  };

  const handleUpdateStatus = (id: string, status: ProductStatus) => {
    setProducts(prev => prev.map(p => p.id === id ? { ...p, status } : p));
  };

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-slate-50">
      <Navbar 
        currentRole={currentRole} 
        onRoleChange={setCurrentRole}
        onSearch={setSearchQuery}
      />

      <main className="flex-1 relative overflow-hidden">
        {currentRole === UserRole.BUYER && (
          <div className="h-full flex flex-col md:flex-row">
            <div className="w-full md:w-1/3 lg:w-1/4 h-1/3 md:h-full border-r bg-white overflow-y-auto p-4 z-10 shadow-lg">
              <h2 className="text-xl font-bold text-green-800 mb-4">Khám phá Nông sản</h2>
              <div className="space-y-4">
                <select 
                  className="w-full p-2 border rounded-lg outline-none focus:ring-2 focus:ring-green-500"
                  onChange={(e) => setCategoryFilter(e.target.value)}
                  value={categoryFilter}
                >
                  <option value="All">Tất cả danh mục</option>
                  <option value="Trái cây">Trái cây</option>
                  <option value="Lúa gạo">Lúa gạo</option>
                  <option value="Rau củ">Rau củ</option>
                </select>

                <div className="space-y-3">
                  {filteredProducts.map(product => (
                    <div key={product.id} className="p-3 border rounded-xl hover:border-green-500 cursor-pointer transition-all bg-white shadow-sm group">
                      <img src={product.images.product[0]} alt={product.name} className="w-full h-32 object-cover rounded-lg mb-2" />
                      <h3 className="font-bold text-slate-800 group-hover:text-green-700">{product.name}</h3>
                      <p className="text-xs text-slate-500">{product.farmerName}</p>
                      <div className="flex flex-wrap gap-1 mt-2">
                        {product.certificates.map((c, idx) => (
                          <span key={idx} className="px-2 py-0.5 bg-green-100 text-green-700 text-[10px] rounded-full font-semibold">
                            {c.type}
                          </span>
                        ))}
                      </div>
                    </div>
                  ))}
                  {filteredProducts.length === 0 && (
                    <p className="text-center text-slate-400 py-10 italic">Không tìm thấy sản phẩm phù hợp.</p>
                  )}
                </div>
              </div>
            </div>
            <div className="flex-1 h-full">
              <MapInterface products={filteredProducts} />
            </div>
          </div>
        )}

        {currentRole === UserRole.FARMER && (
          <div className="h-full overflow-y-auto bg-green-50/30">
             <FarmerPortal onAdd={handleAddProduct} />
          </div>
        )}

        {currentRole === UserRole.ADMIN && (
          <div className="h-full overflow-y-auto p-6">
            <AdminDashboard 
              products={products} 
              onUpdateStatus={handleUpdateStatus} 
            />
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useEffect, useRef, useState } from 'react';
import L from 'leaflet';
import { FarmProduct } from '../types';
import { MapPin, Phone, Star, Award, ExternalLink } from 'lucide-react';

interface MapInterfaceProps {
  products: FarmProduct[];
}

const MapInterface: React.FC<MapInterfaceProps> = ({ products }) => {
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<L.Map | null>(null);
  const markersRef = useRef<L.Marker[]>([]);
  const [selectedProduct, setSelectedProduct] = useState<FarmProduct | null>(null);

  useEffect(() => {
    if (!mapContainerRef.current) return;

    if (!mapRef.current) {
      mapRef.current = L.map(mapContainerRef.current, {
        center: [15.8, 108.2], // Center of Vietnam
        zoom: 6,
        zoomControl: false
      });

      L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        attribution: '© OpenStreetMap contributors'
      }).addTo(mapRef.current);

      L.control.zoom({ position: 'bottomright' }).addTo(mapRef.current);
    }

    // Clear existing markers
    markersRef.current.forEach(m => m.remove());
    markersRef.current = [];

    // Custom Icon Factory
    const createIcon = (category: string) => L.divIcon({
      className: 'custom-div-icon',
      html: `<div class="bg-green-600 p-2 rounded-full border-2 border-white shadow-xl transform transition hover:scale-110">
              <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-leaf"><path d="M11 20A7 7 0 0 1 9.8 6.1C15.5 5 17 4.48 19 2c1 2 2 3.5 2 9.5a7 7 0 0 1-7 7c-2 0-3-1-3-1"/><path d="M11 20s-1 1.5-3.5 1.5-4.5-1.5-4.5-5 4-5 4-5"/></svg>
            </div>`,
      iconSize: [32, 32],
      iconAnchor: [16, 32],
    });

    // Add markers
    products.forEach(p => {
      const marker = L.marker([p.location.lat, p.location.lng], {
        icon: createIcon(p.category)
      })
      .addTo(mapRef.current!)
      .on('click', () => setSelectedProduct(p));

      markersRef.current.push(marker);
    });

    return () => {
      // Clean up if needed, though with mapRef persist we mostly just manage markers
    };
  }, [products]);

  return (
    <div className="relative w-full h-full">
      <div ref={mapContainerRef} className="w-full h-full z-0" />

      {selectedProduct && (
        <div className="absolute bottom-6 left-1/2 transform -translate-x-1/2 w-full max-w-sm px-4 z-[1000] animate-in slide-in-from-bottom-10 duration-300">
          <div className="bg-white rounded-3xl shadow-2xl border border-green-100 overflow-hidden">
            <div className="relative h-48">
              <img src={selectedProduct.images.product[0]} alt={selectedProduct.name} className="w-full h-full object-cover" />
              <button 
                onClick={() => setSelectedProduct(null)}
                className="absolute top-3 right-3 bg-black/30 hover:bg-black/50 text-white p-1.5 rounded-full backdrop-blur-sm transition-all"
              >
                <svg width="20" height="20" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
              </button>
              <div className="absolute bottom-3 left-3 bg-white/90 backdrop-blur px-3 py-1 rounded-full flex items-center gap-1">
                <Star className="text-yellow-500 fill-yellow-500" size={14} />
                <span className="text-sm font-bold text-slate-800">{selectedProduct.rating}</span>
              </div>
            </div>

            <div className="p-5">
              <div className="flex justify-between items-start mb-2">
                <div>
                  <h3 className="text-xl font-bold text-slate-800 leading-tight">{selectedProduct.name}</h3>
                  <p className="text-sm text-green-600 font-medium">{selectedProduct.farmerName}</p>
                </div>
                <div className="bg-green-50 px-2 py-1 rounded-lg">
                  <span className="text-[10px] font-bold text-green-700 uppercase">{selectedProduct.category}</span>
                </div>
              </div>

              <div className="flex items-center gap-2 text-slate-500 text-sm mb-4">
                <MapPin size={14} />
                <span>{selectedProduct.location.address}</span>
              </div>

              <div className="flex flex-wrap gap-2 mb-6">
                {selectedProduct.certificates.map((c, idx) => (
                  <div key={idx} className="flex items-center gap-1 bg-green-50 border border-green-100 px-2 py-1 rounded-md">
                    <Award size={12} className="text-green-600" />
                    <span className="text-xs font-semibold text-green-700">{c.type}</span>
                  </div>
                ))}
              </div>

              <div className="flex gap-2">
                <a 
                  href={`tel:${selectedProduct.contact}`}
                  className="flex-1 bg-green-600 hover:bg-green-700 text-white py-2.5 rounded-xl font-bold text-center flex items-center justify-center gap-2 transition-all shadow-lg shadow-green-200"
                >
                  <Phone size={18} />
                  Gọi Liên Hệ
                </a>
                <button className="p-2.5 border-2 border-slate-100 rounded-xl hover:border-green-200 transition-all text-slate-400 hover:text-green-600">
                  <ExternalLink size={20} />
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

