interface AuthScreenProps {
  onLogin: (user: User) => void;
}

const AuthScreen: React.FC<AuthScreenProps> = ({ onLogin }) => {
  const [activeBranch, setActiveBranch] = useState<UserRole.FARMER | UserRole.ADMIN>(UserRole.FARMER);
  const [mode, setMode] = useState<'LOGIN' | 'REGISTER' | 'OTP'>('LOGIN');

  const [farmerReg, setFarmerReg] = useState({
    farmName: '',
    rep: '',
    cccd: '',
    phone: '',
    province: '',
    district: '',
    commune: '',
    location: null as { lat: number, lng: number } | null
  });

  const [otp, setOtp] = useState('');
  const mapRef = useRef<L.Map | null>(null);
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const markerRef = useRef<L.Marker | null>(null);

  useEffect(() => {
    if (mode === 'REGISTER' && activeBranch === UserRole.FARMER && mapContainerRef.current && !mapRef.current) {
      mapRef.current = L.map(mapContainerRef.current).setView([10.762622, 106.660172], 13);
      L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png').addTo(mapRef.current);

      mapRef.current.on('click', (e: L.LeafletMouseEvent) => {
        const { lat, lng } = e.latlng;
        setFarmerReg(prev => ({ ...prev, location: { lat, lng } }));
        if (markerRef.current) {
          markerRef.current.setLatLng(e.latlng);
        } else {
          markerRef.current = L.marker(e.latlng).addTo(mapRef.current!);
        }
      });
    }
    return () => {
      if (mapRef.current) {
        mapRef.current.remove();
        mapRef.current = null;
        markerRef.current = null;
      }
    };
  }, [mode, activeBranch]);

  const handleFarmerSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!farmerReg.location) return;
    const user: FarmerUser = {
      id: 'f' + Date.now(),
      role: UserRole.FARMER,
      farmName: farmerReg.farmName,
      representative: farmerReg.rep,
      cccd: farmerReg.cccd,
      phone: farmerReg.phone,
      address: { province: farmerReg.province, district: farmerReg.district, commune: farmerReg.commune, detail: '' },
      location: farmerReg.location
    };
    onLogin(user);
  };

  return (
    <div className="min-h-screen bg-slate-100 flex flex-col items-center justify-center p-4">
