              <Landmark size={36} />
            </div>
            <h1 className="text-4xl font-black mb-6 leading-tight">AgroMap VN</h1>
            <p className="text-lg text-white/90 leading-relaxed font-medium">
              {activeBranch === UserRole.FARMER 
                ? "Nơi nông sản Việt vươn tầm thế giới qua số hóa vùng trồng." 
                : "Quản lý dữ liệu nông nghiệp cấp quốc gia an toàn và bảo mật."}
            </p>
          </div>
          <div className="text-sm font-bold opacity-60 tracking-widest">BỘ NÔNG NGHIỆP & PTNT</div>
        </div>

        {/* Right Side: Form */}
        <div className="flex-1 p-8 md:p-14 overflow-y-auto max-h-[95vh]">
          {/* Switcher */}
          <div className="flex bg-slate-200 p-2 rounded-2xl mb-10">
            <button 
              onClick={() => { setActiveBranch(UserRole.FARMER); setMode('LOGIN'); }}
              className={`flex-1 py-4 rounded-xl text-base font-black flex items-center justify-center gap-2 transition-all ${activeBranch === UserRole.FARMER ? 'bg-white text-green-800 shadow-md border border-slate-300' : 'text-slate-600'}`}
            >
              <UserIcon size={20} /> NÔNG DÂN
            </button>
            <button 
              onClick={() => { setActiveBranch(UserRole.ADMIN); setMode('LOGIN'); }}
              className={`flex-1 py-4 rounded-xl text-base font-black flex items-center justify-center gap-2 transition-all ${activeBranch === UserRole.ADMIN ? 'bg-white text-black shadow-md border border-slate-300' : 'text-slate-600'}`}
            >
              <ShieldCheck size={20} /> CÁN BỘ
