            <div className="animate-in fade-in slide-in-from-bottom-6">
              <h2 className="text-3xl font-black text-black mb-2">Đăng nhập</h2>
              <p className="text-slate-700 text-lg mb-8 font-medium italic">Chào mừng bạn quay lại hệ thống.</p>

              <form className="space-y-6">
