                  className={`w-full py-5 rounded-2xl text-white font-black text-xl shadow-lg transition-all transform hover:-translate-y-1 ${activeBranch === UserRole.FARMER ? 'bg-green-700 shadow-green-200' : 'bg-black shadow-slate-300'}`}
                >
                  {activeBranch === UserRole.ADMIN ? 'TIẾP TỤC' : 'ĐĂNG NHẬP'}
                </button>

                <p className="text-center text-lg text-slate-800 mt-8 font-medium">
                  Chưa có tài khoản? 
                  <button type="button" onClick={() => setMode('REGISTER')} className="text-green-700 font-black ml-2 border-b-2 border-green-700">Đăng ký mới</button>
                </p>
              </form>
            </div>
          )}

          {mode === 'REGISTER' && activeBranch === UserRole.FARMER && (
            <div className="animate-in fade-in slide-in-from-right-8">
              <h2 className="text-3xl font-black text-black mb-8">Đăng ký Nông hộ mới</h2>
              <form onSubmit={handleFarmerSubmit} className="space-y-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-2">
                    <label className="text-base font-black text-black uppercase">Tên nhà vườn / HTX *</label>
                    <input required className="w-full bg-white border-2 border-slate-400 p-4 rounded-xl outline-none focus:border-green-600 text-black text-base font-bold" value={farmerReg.farmName} onChange={e => setFarmerReg({...farmerReg, farmName: e.target.value})} />
