    }
    if (step === 2) {
      return (latestProduct.status === ProductStatus.APPROVED) ? 'COMPLETED' : (latestProduct.status === ProductStatus.PENDING ? 'PROCESSING' : 'WAITING');
    }
    if (step === 3) {
      return (latestProduct.status === ProductStatus.APPROVED) ? 'COMPLETED' : 'WAITING';
