                               ? "Vùng trồng của bạn đang HIỂN THỊ công khai." 
                               : "Đang chờ phê duyệt để HIỂN THỊ lên bản đồ."}
                           </p>
                           <button className={`w-full py-5 rounded-2xl font-black text-sm uppercase transition-all border-4 ${
                             product.status === ProductStatus.APPROVED 
                               ? 'bg-green-600 text-white border-green-800 hover:bg-green-700' 
                               : 'bg-white/10 text-white/40 border-white/10 cursor-not-allowed'
                           }`}>
                             XEM TRÊN BẢN ĐỒ QUỐC GIA
                           </button>
                        </div>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Audit History Log */}
      <div className="bg-black p-12 rounded-[4rem] shadow-2xl">
         <div className="flex items-center justify-between mb-10 border-b-2 border-white/20 pb-6">
            <h3 className="text-3xl font-black text-white uppercase tracking-tighter flex items-center gap-4">
              <Calendar size={36} /> NHẬT KÝ HỆ THỐNG (LIVE LOGS)
            </h3>
            <span className="text-green-400 font-black flex items-center gap-2 animate-pulse">
               <div className="w-3 h-3 bg-green-400 rounded-full"></div> TRỰC TUYẾN
            </span>
         </div>
         <div className="space-y-6">
            {[
              { time: '14:20 - Hôm nay', event: 'Hệ thống GovAuth tự động tiếp nhận hồ sơ mã VN-BTE-PUC-001.', type: 'SYSTEM' },
              { time: '10:05 - Hôm qua', event: 'Phòng Nông nghiệp Huyện Châu Thành cập nhật trạng thái: ĐANG KIỂM TRA THỰC ĐỊA.', type: 'USER' },
              { time: '16:45 - 20/05/2024', event: 'Nông hộ hoàn tất đăng ký thông tin ban đầu.', type: 'USER' }
            ].map((log, i) => (
              <div key={i} className="flex flex-col md:flex-row md:items-center justify-between p-6 bg-white/5 rounded-[2rem] border border-white/10 hover:bg-white/10 transition-all">
                <div className="flex items-center gap-6">
                  <div className={`w-3 h-3 rounded-full ${log.type === 'SYSTEM' ? 'bg-blue-400' : 'bg-green-400'}`}></div>
                  <p className="text-lg font-bold text-white/90 leading-tight">{log.event}</p>
                </div>
                <p className="text-xs font-black text-slate-500 uppercase tracking-widest mt-4 md:mt-0 bg-white/5 px-4 py-2 rounded-xl">{log.time}</p>
              </div>
            ))}
         </div>
      </div>
    </div>
  );
};

export default FarmerDashboard;

import React, { useState, useMemo } from 'react';
import { UserRole, FarmProduct, ProductStatus, User, AdminUser, AdminLevel } from './types';
import { MOCK_PRODUCTS } from './constants';
import Navbar from './components/Navbar';
import MapInterface from './components/MapInterface';
import FarmerPortal from './components/FarmerPortal';
import AdminDashboard from './components/AdminDashboard';
import AuthScreen from './components/AuthScreen';
import FarmerProfile from './components/FarmerProfile';
import FarmerAnalytics from './components/FarmerAnalytics';
import { Sprout, Map as MapIcon, User as UserIcon, BarChart3 } from 'lucide-react';

const App: React.FC = () => {
  const [user, setUser] = useState<User>(null);
  const [currentRole, setCurrentRole] = useState<UserRole | null>(null);
  const [products, setProducts] = useState<FarmProduct[]>(MOCK_PRODUCTS);
  const [searchQuery, setSearchQuery] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('All');

  // Navigation for Farmer - Defaulting to 'portal' now
  const [farmerTab, setFarmerTab] = useState<'portal' | 'map' | 'analytics' | 'profile'>('portal');

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      if (user?.role === UserRole.ADMIN) {
        const matchesArea = p.location.address.toLowerCase().includes(user.assignedArea.split(' ').pop()?.toLowerCase() || '');
        if (!matchesArea && user.level !== AdminLevel.CENTRAL) return false;
      }

      const matchesSearch = p.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                          p.farmerName.toLowerCase().includes(searchQuery.toLowerCase());
      const matchesCategory = categoryFilter === 'All' || p.category === categoryFilter;

      const isAdminView = user?.role === UserRole.ADMIN;
      const isApproved = p.status === ProductStatus.APPROVED;

      return matchesSearch && matchesCategory && (isAdminView || isApproved);
    });
  }, [products, searchQuery, categoryFilter, user]);

  const handleAddProduct = (newProduct: FarmProduct) => {
    setProducts(prev => [newProduct, ...prev]);
    // Stay on portal to see the updated list
  };

  const handleUpdateStatus = (id: string, status: ProductStatus, note?: string) => {
    setProducts(prev => prev.map(p => p.id === id ? { 
      ...p, 
      status, 
      verificationNote: note,
      verifiedAt: new Date().toISOString(),
      verifiedBy: user?.role === UserRole.ADMIN ? user.fullName : undefined
    } : p));
  };

  const handleAuthSuccess = (loggedUser: User) => {
    setUser(loggedUser);
    setCurrentRole(loggedUser?.role || UserRole.BUYER);
  };

  const handleLogout = () => {
    setUser(null);
    setCurrentRole(null);
  };

  if (!user) {
    return <AuthScreen onLogin={handleAuthSuccess} />;
  }

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-white">
      <Navbar 
        currentRole={user.role} 
        onRoleChange={() => {}} 
        onSearch={setSearchQuery}
        user={user}
        onLogout={handleLogout}
      />

      <main className="flex-1 relative flex overflow-hidden">
        {user.role === UserRole.FARMER && (
          <>
            {/* Sidebar Navigation for Farmer */}
            <aside className="w-80 bg-white border-r-4 border-black flex flex-col p-6 gap-2">
              <div className="mb-8 p-4 bg-slate-50 rounded-2xl border-2 border-black">
                <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Đang đăng nhập</p>
                <p className="text-lg font-black text-black leading-tight">{(user as any).farmName}</p>
              </div>

              <button 
                onClick={() => setFarmerTab('portal')}
                className={`flex items-center gap-4 px-6 py-4 rounded-2xl font-black text-lg transition-all ${farmerTab === 'portal' ? 'bg-black text-white shadow-xl' : 'text-black hover:bg-slate-100'}`}
              >
                <Sprout size={24} /> QUẢN LÝ VÙNG TRỒNG
              </button>

              <button 
                onClick={() => setFarmerTab('map')}
                className={`flex items-center gap-4 px-6 py-4 rounded-2xl font-black text-lg transition-all ${farmerTab === 'map' ? 'bg-black text-white shadow-xl' : 'text-black hover:bg-slate-100'}`}
              >
                <MapIcon size={24} /> BẢN ĐỒ NÔNG SẢN
              </button>

              <button 
                onClick={() => setFarmerTab('analytics')}
                className={`flex items-center gap-4 px-6 py-4 rounded-2xl font-black text-lg transition-all ${farmerTab === 'analytics' ? 'bg-black text-white shadow-xl' : 'text-black hover:bg-slate-100'}`}
              >
                <BarChart3 size={24} /> THỐNG KÊ SẢN LƯỢNG
              </button>

              <div className="mt-auto border-t-2 border-slate-100 pt-6">
                <button 
                  onClick={() => setFarmerTab('profile')}
                  className={`w-full flex items-center gap-4 px-6 py-4 rounded-2xl font-black text-lg transition-all ${farmerTab === 'profile' ? 'bg-black text-white shadow-xl' : 'text-black hover:bg-slate-100'}`}
                >
                  <UserIcon size={24} /> TÀI KHOẢN CÁ NHÂN
                </button>
              </div>
            </aside>

            {/* Content Area for Farmer */}
            <div className="flex-1 h-full overflow-y-auto bg-slate-50">
              {farmerTab === 'portal' && (
                <FarmerPortal 
                  onAdd={handleAddProduct} 
                  existingProducts={products.filter(p => p.farmerId === 'f_current' || p.farmerId === user.id)}
                />
              )}
              {farmerTab === 'map' && (
                <div className="h-full relative">
                  <MapInterface products={filteredProducts} isFarmerView={true} />
                  <div className="absolute top-6 left-6 z-[1000] bg-white border-4 border-black p-4 rounded-2xl shadow-2xl">
                    <h3 className="text-sm font-black text-black uppercase tracking-tighter mb-2">Chế độ Bản đồ</h3>
                    <p className="text-[10px] font-bold text-slate-600 mb-4">Bạn đang xem vị trí vùng trồng toàn quốc.</p>
                    <button className="w-full bg-green-700 text-white py-2 rounded-xl font-black text-xs uppercase hover:bg-green-800 transition-all shadow-md">
                      Ghim lại vị trí của tôi
                    </button>
                  </div>
                </div>
              )}
              {farmerTab === 'analytics' && (
                <FarmerAnalytics products={products.filter(p => p.farmerId === 'f_current' || p.farmerId === user.id)} />
              )}
              {farmerTab === 'profile' && (
                <FarmerProfile user={user as any} />
              )}
            </div>
          </>
        )}

        {user.role === UserRole.ADMIN && (
          <div className="h-full overflow-y-auto w-full bg-slate-50">
            <AdminDashboard 
              products={products} 
              onUpdateStatus={handleUpdateStatus} 
              admin={user as AdminUser}
            />
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { FarmProduct, ProductStatus, CertType } from '../types';
import { CATEGORIES } from '../constants';
import { 
  ShieldCheck, Calendar, Info, AlertTriangle, CheckCircle2, 
  X, UploadCloud, Sprout, Search, ChevronRight, MapPin
} from 'lucide-react';

interface FarmerPortalProps {
  onAdd: (product: FarmProduct) => void;
  existingProducts: FarmProduct[];
}

const FarmerPortal: React.FC<FarmerPortalProps> = ({ onAdd, existingProducts }) => {
  const [activeTab, setActiveTab] = useState<'register' | 'my-farms'>('register');
  const fileInputRefs = useRef<{ [key: string]: HTMLInputElement | null }>({});

  const [formData, setFormData] = useState({
    name: '',
    variety: '',
    category: CATEGORIES[0],
    area: 0,
    yield: 0,
    description: '',
    contact: '',
    regionCode: '',
    address: 'Vĩnh Long, Việt Nam',
    harvestMonths: [] as number[],
    certs: [] as { type: CertType, proofUrl: string, expiryDate: string }[],
  });

  const [images, setImages] = useState({ orchard: '', product: '', warehouse: '' });

  const handleFileChange = (certType: CertType, e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = reader.result as string;
        setFormData(prev => {
          const existing = prev.certs.find(c => c.type === certType);
          if (existing) {
            return {
              ...prev,
              certs: prev.certs.map(c => c.type === certType ? { ...c, proofUrl: base64String } : c)
            };
          } else {
            return {
              ...prev,
              certs: [...prev.certs, { type: certType, proofUrl: base64String, expiryDate: '2026-12-31' }]
            };
          }
        });
      };
      reader.readAsDataURL(file);
    }
  };

  const removeCert = (certType: CertType) => {
    setFormData(prev => ({
      ...prev,
      certs: prev.certs.filter(c => c.type !== certType)
    }));
  };

  const toggleMonth = (m: number) => {
    setFormData(prev => ({
      ...prev,
      harvestMonths: prev.harvestMonths.includes(m) 
        ? prev.harvestMonths.filter(item => item !== m) 
        : [...prev.harvestMonths, m].sort((a,b) => a-b)
    }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.regionCode || formData.harvestMonths.length === 0) {
      alert("Vui lòng điền đầy đủ thông tin (*) để tiếp tục.");
      return;
    }
    const newProduct: FarmProduct = {
      id: Math.random().toString(36).substr(2, 9),
      farmerId: 'f_current',
      farmerName: 'HTX Nông Nghiệp Xanh',
      name: formData.name,
      variety: formData.variety,
      category: formData.category,
      area: formData.area,
      expectedYield: formData.yield,
      description: formData.description,
      harvestMonths: formData.harvestMonths,
      images: { 
        orchard: [images.orchard || 'https://picsum.photos/600/400'], 
        product: [images.product || 'https://picsum.photos/600/400'], 
        warehouse: [images.warehouse || 'https://picsum.photos/600/400'] 
      },
      certificates: formData.certs.map(c => ({ 
        type: c.type, 
        proofUrl: c.proofUrl, 
        issueDate: new Date().toISOString().split('T')[0],
        expiryDate: c.expiryDate
      })),
      regionCode: formData.regionCode,
      location: { lat: 10.2, lng: 105.8, address: formData.address },
      status: ProductStatus.PENDING,
      contact: formData.contact,
      rating: 0,
      timeline: [],
      updatedAt: new Date().toISOString()
    };
    onAdd(newProduct);
    setActiveTab('my-farms');
  };

  return (
    <div className="max-w-6xl mx-auto py-10 px-4">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-10 gap-6">
        <div>
          <h1 className="text-5xl font-black text-black mb-2 tracking-tighter uppercase">Quản lý Vùng trồng</h1>
          <p className="text-xl text-slate-700 font-bold">Cổng đăng ký và vận hành dữ liệu sản xuất Nông hộ.</p>
        </div>
        <div className="flex bg-white p-2 rounded-2xl shadow-md border-4 border-black">
          <button 
            onClick={() => setActiveTab('register')}
            className={`px-8 py-3 rounded-xl text-lg font-black transition-all ${activeTab === 'register' ? 'bg-black text-white shadow-lg' : 'text-slate-800'}`}
          >
            ĐĂNG KÝ MỚI
          </button>
          <button 
            onClick={() => setActiveTab('my-farms')}
            className={`px-8 py-3 rounded-xl text-lg font-black transition-all ${activeTab === 'my-farms' ? 'bg-black text-white shadow-lg' : 'text-slate-800'}`}
          >
            DANH SÁCH VƯỜN ({existingProducts.length})
          </button>
        </div>
      </div>

      {activeTab === 'register' ? (
        <form onSubmit={handleSubmit} className="grid grid-cols-1 lg:grid-cols-12 gap-8 animate-in fade-in duration-500">
          <div className="lg:col-span-7 space-y-8">
            <div className="bg-white rounded-[2.5rem] p-10 shadow-sm border-2 border-slate-200">
              <div className="flex items-center gap-3 mb-8 text-black font-black text-2xl border-b-4 border-green-700 pb-4">
                <Info size={28} className="text-green-700" />
                <span className="uppercase tracking-tighter">Thông tin Vùng trồng</span>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="md:col-span-2 space-y-2">
                  <label className="block text-base font-black text-black uppercase">Tên Nông sản & Vùng trồng *</label>
                  <input required className="w-full p-4 bg-white border-2 border-slate-400 rounded-2xl focus:border-green-600 outline-none text-black font-bold text-lg" placeholder="Ví dụ: Bưởi da xanh Châu Thành" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
                </div>

                <div className="space-y-2">
                  <label className="block text-base font-black text-black uppercase">Giống cây trồng</label>
                  <input className="w-full p-4 bg-white border-2 border-slate-400 rounded-2xl focus:border-green-600 outline-none text-black font-bold text-lg" placeholder="Ri6, Da xanh..." value={formData.variety} onChange={e => setFormData({...formData, variety: e.target.value})} />
                </div>

                <div className="space-y-2">
                  <label className="block text-base font-black text-black uppercase">Nhóm nông sản</label>
                  <select className="w-full p-4 bg-white border-2 border-slate-400 rounded-2xl focus:border-green-600 outline-none text-black font-bold text-lg appearance-none" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                    {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                </div>

                <div className="space-y-2">
                  <label className="block text-base font-black text-black uppercase">Diện tích (ha) *</label>
                  <input required type="number" step="0.1" className="w-full p-4 bg-white border-2 border-slate-400 rounded-2xl focus:border-green-600 outline-none text-black font-bold text-lg" value={formData.area} onChange={e => setFormData({...formData, area: parseFloat(e.target.value)})} />
                </div>

                <div className="space-y-2">
                  <label className="block text-base font-black text-black uppercase">Sản lượng dự kiến (tấn)</label>
                  <input type="number" className="w-full p-4 bg-white border-2 border-slate-400 rounded-2xl focus:border-green-600 outline-none text-black font-bold text-lg" value={formData.yield} onChange={e => setFormData({...formData, yield: parseFloat(e.target.value)})} />
                </div>
              </div>

              <div className="mt-12">
                <label className="block text-xl font-black text-black mb-6 flex items-center gap-3">
                  <Calendar size={24} className="text-green-700" />
                  THÁNG THU HOẠCH CHÍNH VỤ *
                </label>
                <div className="grid grid-cols-4 sm:grid-cols-6 gap-3">
                  {[...Array(12)].map((_, i) => (
                    <button
                      key={i}
                      type="button"
                      onClick={() => toggleMonth(i + 1)}
                      className={`py-4 rounded-xl text-lg font-black transition-all border-2 ${formData.harvestMonths.includes(i + 1) ? 'bg-green-700 text-white border-green-800 shadow-md scale-105' : 'bg-slate-50 text-black border-slate-300 hover:border-green-600'}`}
                    >
                      T{i + 1}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          </div>

          <div className="lg:col-span-5 space-y-8">
            <div className="bg-white rounded-[2.5rem] p-10 shadow-sm border-2 border-slate-200">
              <div className="flex items-center gap-3 mb-8 text-black font-black text-2xl border-b-4 border-green-700 pb-4">
                <ShieldCheck size={28} className="text-green-700" />
                <span className="uppercase tracking-tighter">Định danh & Minh chứng</span>
              </div>

              <div className="space-y-8">
                <div className="space-y-2">
                  <label className="block text-base font-black text-black uppercase tracking-tight">Mã số vùng trồng (PUC) *</label>
                  <input required className="w-full p-4 bg-green-50 border-2 border-green-800 rounded-2xl focus:ring-4 focus:ring-green-100 outline-none font-mono text-xl font-black text-green-900" placeholder="VN-BTE-01-02-123" value={formData.regionCode} onChange={e => setFormData({...formData, regionCode: e.target.value.toUpperCase()})} />
                  <p className="text-sm font-bold text-red-700 flex items-center gap-2 mt-2 italic">
                    <AlertTriangle size={16} />
                    Dữ liệu này sẽ được hậu kiểm bởi cơ quan chuyên môn.
                  </p>
                </div>

                <div className="space-y-4">
                  <label className="block text-base font-black text-black uppercase tracking-tight">Tải lên ảnh chụp Chứng chỉ *</label>
                  <div className="grid grid-cols-2 gap-4">
                    {Object.values(CertType).map(cert => {
                      const certData = formData.certs.find(c => c.type === cert);
                      return (
                        <div key={cert} className="relative">
                          <input 
                            type="file" 
                            accept="image/*" 
                            className="hidden" 
                            ref={el => { fileInputRefs.current[cert] = el; }}
                            onChange={(e) => handleFileChange(cert, e)}
                          />

                          <div 
                            onClick={() => !certData && fileInputRefs.current[cert]?.click()}
                            className={`h-40 border-2 rounded-2xl transition-all cursor-pointer flex flex-col items-center justify-center gap-2 text-center overflow-hidden relative group ${certData ? 'border-green-700 bg-white' : 'border-slate-300 bg-slate-50 hover:border-green-600 border-dashed'}`}
                          >
                            {certData ? (
                              <>
                                <img src={certData.proofUrl} alt={cert} className="absolute inset-0 w-full h-full object-cover opacity-30" />
                                <div className="relative z-10 p-2">
                                  <div className="bg-green-700 text-white p-1.5 rounded-full mx-auto mb-2 w-fit">
                                    <CheckCircle2 size={24} />
                                  </div>
                                  <p className="text-lg font-black text-black leading-none">{cert}</p>
                                  <p className="text-[10px] font-black text-green-800 uppercase mt-1">Đã có minh chứng</p>
                                </div>
                                <button 
                                  type="button" 
                                  onClick={(e) => { e.stopPropagation(); removeCert(cert); }}
                                  className="absolute top-2 right-2 p-1.5 bg-red-600 text-white rounded-lg shadow-md z-20 hover:scale-110 transition-transform"
                                >
                                  <X size={16} />
                                </button>
                              </>
                            ) : (
                              <div className="p-4 flex flex-col items-center">
                                <UploadCloud size={32} className="text-slate-400 mb-2 group-hover:text-green-700 transition-colors" />
                                <p className="text-base font-black text-black leading-tight">{cert}</p>
                                <p className="text-[10px] font-bold text-slate-500 uppercase mt-1">Chưa chọn ảnh</p>
                              </div>
                            )}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              </div>
            </div>

            <button 
              type="submit"
              className="w-full bg-green-700 hover:bg-green-800 text-white py-6 rounded-3xl font-black text-2xl shadow-2xl transition-all transform hover:-translate-y-2 flex items-center justify-center gap-4 border-b-8 border-green-900 active:translate-y-0 active:border-b-0"
            >
              <CheckCircle2 size={32} />
              XÁC NHẬN & GỬI DUYỆT
            </button>
          </div>
        </form>
      ) : (
        <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
           {existingProducts.length === 0 ? (
             <div className="bg-white border-4 border-dashed border-slate-300 rounded-[3rem] p-24 text-center">
                <Sprout size={64} className="mx-auto text-slate-200 mb-6" />
                <p className="text-2xl font-black text-slate-400 uppercase tracking-widest">Bạn chưa đăng ký vùng trồng nào</p>
                <button onClick={() => setActiveTab('register')} className="mt-4 text-black font-black underline uppercase">Đăng ký ngay</button>
             </div>
           ) : (
             <div className="grid grid-cols-1 gap-6">
                {existingProducts.map(p => (
                  <div key={p.id} className="bg-white p-8 rounded-[2.5rem] border-4 border-black flex flex-col md:flex-row items-center justify-between hover:shadow-2xl transition-all group">
                    <div className="flex items-center gap-10">
                      <div className="w-24 h-24 rounded-2xl border-4 border-black overflow-hidden shrink-0">
                        <img src={p.images.product[0]} alt={p.name} className="w-full h-full object-cover" />
                      </div>
