              >
                <Sprout size={24} /> QUẢN LÝ VÙNG TRỒNG
              </button>

              <button 
                onClick={() => setFarmerTab('map')}
                className={`flex items-center gap-4 px-6 py-4 rounded-2xl font-black text-lg transition-all ${farmerTab === 'map' ? 'bg-black text-white shadow-xl' : 'text-black hover:bg-slate-100'}`}
              >
                <MapIcon size={24} /> BẢN ĐỒ NÔNG SẢN
              </button>

              <div className="mt-auto border-t-2 border-slate-100 pt-6">
                <button 
                  onClick={() => setFarmerTab('profile')}
                  className={`w-full flex items-center gap-4 px-6 py-4 rounded-2xl font-black text-lg transition-all ${farmerTab === 'profile' ? 'bg-black text-white shadow-xl' : 'text-black hover:bg-slate-100'}`}
                >
                  <UserIcon size={24} /> TÀI KHOẢN CÁ NHÂN
                </button>
              </div>
            </aside>

            {/* Content Area for Farmer */}
            <div className="flex-1 h-full overflow-y-auto bg-slate-50">
