        const base64String = reader.result as string;
        setFormData(prev => {
          const existing = prev.certs.find(c => c.type === certType);
          if (existing) {
            return {
              ...prev,
              certs: prev.certs.map(c => c.type === certType ? { ...c, proofUrl: base64String } : c)
            };
