interface MapInterfaceProps {
  products: FarmProduct[];
  isFarmerView?: boolean;
  onSearch?: (query: string) => void;
  initialSearchQuery?: string;
}

const POPULAR_SUGGESTIONS = ['Bưởi Da Xanh', 'Sầu riêng Ri6', 'Xoài Cát Hòa Lộc', 'Lúa ST25', 'Vú sữa Lò Rèn'];

const MapInterface: React.FC<MapInterfaceProps> = ({ products, isFarmerView = false, onSearch, initialSearchQuery = '' }) => {
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<L.Map | null>(null);
  const markersRef = useRef<L.Marker[]>([]);
  const [selectedProduct, setSelectedProduct] = useState<FarmProduct | null>(null);
  const [localQuery, setLocalQuery] = useState(initialSearchQuery);
  const [showSuggestions, setShowSuggestions] = useState(false);

  // Initialize Map
  useEffect(() => {
    if (!mapContainerRef.current) return;
    if (!mapRef.current) {
      mapRef.current = L.map(mapContainerRef.current, {
        center: [10.2435, 106.3756], // Centered around Mekong Delta by default
        zoom: 10,
        zoomControl: false
      });
      L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png').addTo(mapRef.current);
      L.control.zoom({ position: 'bottomright' }).addTo(mapRef.current);
    }
  }, []);

  // Handle Markers and Auto-Zoom
  useEffect(() => {
    if (!mapRef.current) return;

    // Clear old markers
    markersRef.current.forEach(m => m.remove());
    markersRef.current = [];

    const createIcon = (color = '#15803d') => L.divIcon({
      className: 'custom-icon',
      html: `<div style="background-color: ${color};" class="p-2 rounded-full border-4 border-black shadow-2xl transform hover:scale-125 transition-all">
              <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M11 20A7 7 0 0 1 9.8 6.1C15.5 5 17 4.48 19 2c1 2 2 3.5 2 9.5a7 7 0 0 1-7 7c-2 0-3-1-3-1"/><path d="M11 20s-1 1.5-3.5 1.5-4.5-1.5-4.5-5 4-5 4-5"/></svg>
            </div>`,
      iconSize: [36, 36],
      iconAnchor: [18, 36],
    });

    const newMarkers: L.Marker[] = [];
    products.forEach(p => {
      const marker = L.marker([p.location.lat, p.location.lng], { icon: createIcon() })
        .addTo(mapRef.current!)
        .on('click', () => setSelectedProduct(p));
      newMarkers.push(marker);
    });
    markersRef.current = newMarkers;

    // Auto-fit bounds if we have products and a search is active
    if (newMarkers.length > 0 && localQuery.length > 0) {
      const group = L.featureGroup(newMarkers);
      mapRef.current.fitBounds(group.getBounds().pad(0.2), { animate: true });
    }
  }, [products, localQuery]);

  const handleSearchSubmit = (q: string) => {
    setLocalQuery(q);
    onSearch?.(q);
    setShowSuggestions(false);
  };

  const handleClearSearch = () => {
    setLocalQuery('');
    onSearch?.('');
    setShowSuggestions(false);
  };

  const openInGoogleMaps = (lat: number, lng: number) => {
    window.open(`https://www.google.com/maps/dir/?api=1&destination=${lat},${lng}`, '_blank');
  };

  return (
    <div className="relative w-full h-full font-sans">
      <div ref={mapContainerRef} className="w-full h-full z-0" />

      {/* Floating Interactive Search Bar */}
      <div className="absolute top-6 left-6 right-6 z-[2000]">
        <div className="max-w-xl mx-auto relative">
          <div className="bg-white border-4 border-black rounded-3xl shadow-[8px_8px_0px_0px_rgba(0,0,0,1)] flex items-center p-2 group focus-within:translate-x-1 focus-within:translate-y-1 focus-within:shadow-none transition-all">
            <div className="pl-4 pr-3 text-black">
              <Search size={24} strokeWidth={3} />
            </div>
            <input 
              type="text" 
              value={localQuery}
              placeholder="Tìm xoài, bưởi, sầu riêng, mã PUC..."
              className="flex-1 py-3 text-lg font-black text-black outline-none placeholder:text-slate-400 uppercase tracking-tighter"
              onChange={(e) => {
                setLocalQuery(e.target.value);
                onSearch?.(e.target.value);
              }}
              onFocus={() => setShowSuggestions(true)}
            />
            {localQuery && (
              <button 
                onClick={handleClearSearch}
                className="p-2 hover:bg-slate-100 rounded-full transition-colors mr-1"
              >
                <X size={20} strokeWidth={3} className="text-slate-500" />
              </button>
            )}
            <button className="bg-black text-white p-3 rounded-2xl hover:scale-105 transition-transform active:scale-95">
              <SlidersHorizontal size={20} strokeWidth={3} />
            </button>
          </div>

          {/* Smart Suggestions Dropdown */}
          {showSuggestions && !localQuery && (
            <div className="absolute top-full mt-4 left-0 right-0 bg-white border-4 border-black rounded-[2rem] shadow-2xl p-6 animate-in slide-in-from-top-4 duration-300">
              <h4 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-4">Gợi ý phổ biến</h4>
              <div className="flex flex-wrap gap-3">
                {POPULAR_SUGGESTIONS.map((s) => (
                  <button 
                    key={s}
                    onClick={() => handleSearchSubmit(s)}
                    className="px-5 py-2.5 bg-slate-50 border-2 border-slate-200 rounded-2xl text-sm font-black text-black hover:border-black hover:bg-white transition-all shadow-sm"
                  >
                    {s}
                  </button>
