            <div className="relative h-56">
              <img src={selectedProduct.images.product[0]} alt={selectedProduct.name} className="w-full h-full object-cover" />
              <button 
                onClick={() => setSelectedProduct(null)}
                className="absolute top-4 right-4 bg-black text-white p-2 rounded-full transition-all shadow-lg hover:bg-red-700"
              >
                <X size={24} strokeWidth={3} />
              </button>
              <div className="absolute bottom-4 left-4 flex gap-2">
                 <span className="bg-black text-white px-4 py-2 rounded-xl font-black text-[10px] uppercase tracking-widest border border-white/20 shadow-xl">Mã PUC: {selectedProduct.regionCode}</span>
                 <span className="bg-green-600 text-white px-4 py-2 rounded-xl font-black text-[10px] uppercase tracking-widest border border-white/20 shadow-xl">{selectedProduct.category}</span>
              </div>
            </div>

            <div className="p-8">
              <div className="mb-4">
                <div className="flex items-center justify-between mb-1">
                   <h3 className="text-3xl font-black text-black leading-none uppercase tracking-tighter">{selectedProduct.name}</h3>
                   <div className="flex items-center gap-1 text-orange-500">
                      <Award size={20} fill="currentColor" />
