                <p className="text-xl text-green-800 font-black italic">{selectedProduct.farmerName}</p>
              </div>

              <div className="flex items-start gap-3 text-slate-900 text-base font-bold mb-8 bg-slate-50 p-4 rounded-2xl border-2 border-slate-100">
                <MapPin size={22} className="text-red-700 shrink-0 mt-1" />
                <span className="leading-tight">{selectedProduct.location.address}</span>
              </div>

              <div className="flex gap-4">
                <a 
                  href={`tel:${selectedProduct.contact}`}
                  className="flex-1 bg-green-700 hover:bg-green-800 text-white py-4 rounded-2xl font-black text-xl text-center flex items-center justify-center gap-3 shadow-xl transition-all active:scale-95 border-b-8 border-green-900"
                >
                  <Phone size={24} strokeWidth={3} />
                  LIÊN HỆ
                </a>
                <button 
                  onClick={() => openInGoogleMaps(selectedProduct.location.lat, selectedProduct.location.lng)}
                  className="px-6 py-4 bg-white border-4 border-black rounded-2xl hover:bg-slate-50 transition-all text-black shadow-lg active:scale-95 flex items-center justify-center"
                >
                  <MapIcon size={28} strokeWidth={3} />
                </button>
              </div>

              <div className="mt-6 text-center">
                 <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest italic">Cập nhật lần cuối: {new Date(selectedProduct.updatedAt).toLocaleDateString('vi-VN')}</p>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Map Overlay Backdrop for Suggestions */}
      {showSuggestions && (
        <div 
          className="absolute inset-0 bg-black/10 z-[1900] backdrop-blur-[2px]" 
          onClick={() => setShowSuggestions(false)}
        />
      )}
    </div>
  );
};

